it('answers a list_sessions at once while a run is pending', async () => {
  const store = new InMemorySessionStore();
  const h = gated(1);
  // history: {enabled: true} is needed for handleListSessions to proceed
  const handle = createMessageHandler(
    {processMessageStream: async function* () {}} as unknown as ChatOrchestrator,
    store,
    {enabled: true}
  );
  const run = h.send(userMessage('A'));
  await afterPendingWork();
  void handle(
    {send: (raw: string) => h.sent.push(JSON.parse(raw))} as unknown as WebSocket,
    h.session,
    {type: 'list_sessions'}
  );
  await afterPendingWork();
  const beforeTheRunEnds = h.frames();
  h.release(0);
  await run;

  expect(beforeTheRunEnds).toEqual(['upsert 0 user "A"', 'upsert 1 assistant ""', 'delta 1 "answer 0"', 'list 0']);
});

describe('configuration warnings', () => {
  const warnings: string[] = [];

  beforeEach(() => {
    warnings.length = 0;
    const collect = (category: string, message: string) => {
      if (category === 'server') warnings.push(message);
    };
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: collect,
      error: () => undefined,
    });
  });

  afterEach(() => {
    setLogger();
  });

  it('warns when history is enabled without resume', () => {
    createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: jest.fn() as unknown as WsAuthenticator,
      sessionStore: {} as unknown as SessionStore,
      orchestrator: {} as unknown as ChatOrchestrator,
      history: {enabled: true},
    });

    expect(warnings).toContain(
      'transport.history enabled without transport.resume: conversation list will be reachable but rows cannot be rejoined'
    );
  });
});

